#!/usr/bin/env bash
# Publish this repo's rules, skills, and Pi packages into user-level agent config folders.
# Additive by default: existing non-link files/dirs are left untouched; our own
# links and generated files are refreshed. Safe to re-run anytime (e.g. after
# `git pull`). Pass --clean to wipe managed folders and republish instead.
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
RULES_SRC="$REPO_ROOT/rules"
SKILLS_SRC="$REPO_ROOT/skills"
PI_PACKAGES_SRC="$REPO_ROOT/pi/packages"
PI_THEMES_SRC="$REPO_ROOT/pi/themes"
PI_KEYBINDINGS_SRC="$REPO_ROOT/pi/keybindings.json"
CLAUDE_SETTINGS_SRC="$REPO_ROOT/claude/settings.json"
MERGE_JSON="$REPO_ROOT/scripts/merge-json.mjs"
GENERATED_MARKER="Generated by ChekTek/ai scripts/update-config"

CLAUDE_RULES_DEST="$HOME/.claude/rules"
CLAUDE_SKILLS_DEST="$HOME/.claude/skills"
CLAUDE_SETTINGS_DEST="$HOME/.claude/settings.json"
COPILOT_SKILLS_DEST="$HOME/.copilot/skills"
COPILOT_INSTRUCTIONS_DEST="${COPILOT_CLI_INSTRUCTIONS_DIR:-$HOME/.copilot/instructions}"
PI_SKILLS_DEST="$HOME/.pi/agent/skills"
PI_EXTENSIONS_DEST="$HOME/.pi/agent/extensions"
PI_THEMES_DEST="$HOME/.pi/agent/themes"
PI_KEYBINDINGS_DEST="$HOME/.pi/agent/keybindings.json"
PI_RULES_DEST="$HOME/.pi/agent/rules"
PI_LEGACY_RULES_DEST="$HOME/.pi/agent/AGENTS.md"
CODEX_ROOT="${CODEX_HOME:-$HOME/.codex}"
CODEX_SKILLS_DEST="$CODEX_ROOT/skills"
CODEX_RULES_DEST="$CODEX_ROOT/AGENTS.md"
LEGACY_PI_CURSOR_SDK_PACKAGE="git:github.com/fitchmultz/pi-cursor-sdk"

CLEAN=0
ASSUME_YES=0
SKILL_DIRS=()

usage() {
  cat <<'USAGE'
Usage: update-config.sh [--clean] [--yes] [--help]

  --clean  Remove everything from the managed skill/rule/extension folders
           before republishing. Legacy generated Pi and current Codex AGENTS.md
           files are removed only when this script owns them.
  --yes    Skip the --clean confirmation prompt.
  --help   Show this message.

Without --clean the script is additive and never replaces files it did not
create or link. Claude settings are always merged into the existing file, never
replaced or removed. An unmanaged Codex AGENTS.md causes an error because the script
cannot install the configured global rules safely.
USAGE
}

while [ "$#" -gt 0 ]; do
  case "$1" in
    --clean|--fresh) CLEAN=1 ;;
    -y|--yes) ASSUME_YES=1 ;;
    -h|--help) usage; exit 0 ;;
    *)
      echo "unknown option: $1" >&2
      usage >&2
      exit 2
      ;;
  esac
  shift
done

# Prints __MISSING__ when metadata.targets is absent or __VALUE__<value> when
# present. Only a scalar comma-separated value is supported so every harness
# sees standards-compatible Agent Skills metadata.
target_spec() {
  file="$1"
  awk '
    NR == 1 {
      sub(/\r$/, "")
      if ($0 != "---") {
        print "__MISSING__"
        exit
      }
      in_frontmatter = 1
      next
    }
    in_frontmatter {
      line = $0
      sub(/\r$/, "", line)

      if (line == "---") {
        if (!found) print "__MISSING__"
        exit
      }

      if (line ~ /^metadata:.*targets[[:space:]]*:/ ||
          (!in_metadata && line ~ /^[[:space:]]*targets[[:space:]]*:/)) {
        print "__INVALID_LOCATION__"
        exit
      }

      if (line ~ /^metadata:[[:space:]]*$/) {
        in_metadata = 1
        next
      }

      if (line ~ /^[^[:space:]]/) in_metadata = 0

      if (in_metadata && line ~ /^[[:space:]]+targets[[:space:]]*:/) {
        if (found) {
          print "__DUPLICATE__"
          exit
        }

        found = 1
        sub(/^[[:space:]]+targets[[:space:]]*:[[:space:]]*/, "", line)
        sub(/[[:space:]]+$/, "", line)

        first = substr(line, 1, 1)
        last = substr(line, length(line), 1)
        if ((first == "\"" && last == "\"") || (first == "\047" && last == "\047")) {
          line = substr(line, 2, length(line) - 2)
        }

        print "__VALUE__" line
      }
    }
  ' "$file"
}

validate_file_targets() {
  file="$1"
  parsed="$(target_spec "$file")"

  case "$parsed" in
    __MISSING__) return 0 ;;
    __INVALID_LOCATION__)
      echo "invalid targets in $file: put targets under metadata" >&2
      return 1
      ;;
    __DUPLICATE__)
      echo "invalid targets in $file: metadata.targets is defined more than once" >&2
      return 1
      ;;
    __VALUE__*) spec="${parsed#__VALUE__}" ;;
    *)
      echo "invalid targets in $file: could not parse metadata.targets" >&2
      return 1
      ;;
  esac

  if [ -z "$spec" ]; then
    echo "invalid targets in $file: metadata.targets cannot be empty" >&2
    return 1
  fi

  printf '%s\n' "$spec" | awk -F, -v file="$file" '
    {
      for (i = 1; i <= NF; i++) {
        target = $i
        gsub(/^[[:space:]]+|[[:space:]]+$/, "", target)

        if (target == "") {
          printf "invalid targets in %s: empty target\n", file > "/dev/stderr"
          exit 1
        }

        if (target != "claude" && target != "copilot" && target != "pi" && target != "codex") {
          printf "invalid targets in %s: unknown target %s (allowed: claude, copilot, pi, codex)\n", file, target > "/dev/stderr"
          exit 1
        }

        if (seen[target]++) {
          printf "invalid targets in %s: duplicate target %s\n", file, target > "/dev/stderr"
          exit 1
        }
      }
    }
  '
}

has_target() {
  file="$1"
  wanted="$2"
  parsed="$(target_spec "$file")"
  [ "$parsed" != "__MISSING__" ] || return 0
  spec="${parsed#__VALUE__}"

  printf '%s\n' "$spec" | awk -F, -v wanted="$wanted" '
    {
      for (i = 1; i <= NF; i++) {
        target = $i
        gsub(/^[[:space:]]+|[[:space:]]+$/, "", target)
        if (target == wanted) exit 0
      }
      exit 1
    }
  '
}

# Grouping directories may nest freely. Stop at each skill root so bundled
# references, scripts, and assets are never treated as separate skills.
discover_skills() {
  local directory="$1" entry
  for entry in "$directory"/*; do
    [ -e "$entry" ] || continue
    if [ -f "$entry" ] && [ "$(basename "$entry")" = "README.md" ]; then
      continue
    fi
    if [ ! -d "$entry" ]; then
      echo "invalid skill source: $entry must be a skill or grouping directory" >&2
      return 1
    fi
    if [ -f "$entry/SKILL.md" ]; then
      SKILL_DIRS+=("$entry")
    else
      discover_skills "$entry"
    fi
  done
}

validate_sources() {
  [ -d "$RULES_SRC" ] || { echo "missing source directory: $RULES_SRC" >&2; exit 1; }
  [ -d "$SKILLS_SRC" ] || { echo "missing source directory: $SKILLS_SRC" >&2; exit 1; }
  [ -d "$PI_PACKAGES_SRC" ] || { echo "missing source directory: $PI_PACKAGES_SRC" >&2; exit 1; }
  [ -d "$PI_THEMES_SRC" ] || { echo "missing source directory: $PI_THEMES_SRC" >&2; exit 1; }
  [ -f "$PI_KEYBINDINGS_SRC" ] || { echo "missing source file: $PI_KEYBINDINGS_SRC" >&2; exit 1; }
  [ -f "$CLAUDE_SETTINGS_SRC" ] || { echo "missing source file: $CLAUDE_SETTINGS_SRC" >&2; exit 1; }
  command -v node >/dev/null 2>&1 || { echo "node is required to merge Claude settings" >&2; exit 1; }
  # The destination is checked too so a broken user file fails before publishing.
  node "$MERGE_JSON" check "$CLAUDE_SETTINGS_SRC" "$CLAUDE_SETTINGS_DEST"

  discover_skills "$SKILLS_SRC"
  # Guard empty arrays for macOS Bash 3.2 with nounset enabled.
  # Published names must also be unique on case-insensitive filesystems.
  printf '%s\n' ${SKILL_DIRS[@]+"${SKILL_DIRS[@]}"} | awk -F/ '
    NF {
      name = tolower($NF)
      if (name in seen) {
        printf "duplicate skill name %s: %s and %s\n", $NF, seen[name], $0 > "/dev/stderr"
        exit 1
      }
      seen[name] = $0
    }
  '
  for skill_dir in ${SKILL_DIRS[@]+"${SKILL_DIRS[@]}"}; do
    validate_file_targets "$skill_dir/SKILL.md"
  done

  find "$RULES_SRC" -type f -name '*.md' -print0 | while IFS= read -r -d '' rule; do
    validate_file_targets "$rule"
  done
}

is_owned_link() {
  target="$1"
  [ -L "$target" ] || return 1
  # Dangling links at managed destinations are leftover publishes (often an
  # old worktree) and are safe to replace.
  [ -e "$target" ] || return 0
  link_target="$(readlink "$target")"
  case "$link_target" in
    "$REPO_ROOT"/*) return 0 ;;
    *) return 1 ;;
  esac
}

is_generated_file() {
  target="$1"
  [ -f "$target" ] && grep -q "$GENERATED_MARKER" "$target"
}

has_global_rules_for() {
  target_name="$1"
  find "$RULES_SRC" -type f -name '*.md' -print | (
    found=0
    while IFS= read -r rule; do
      if has_target "$rule" "$target_name"; then
        found=1
        break
      fi
    done
    [ "$found" -eq 1 ]
  )
}

validate_global_rules_destination() {
  target_name="$1"
  destination="$2"
  label="$3"

  [ -e "$destination" ] || return 0
  is_generated_file "$destination" && return 0
  has_global_rules_for "$target_name" || return 0

  echo "cannot generate $label: $destination already exists and is not managed by this repo" >&2
  echo "move its contents into rules/ or remove it, then run this script again" >&2
  return 1
}

# Folders emptied by --clean, as "directory<TAB>label".
clean_targets() {
  printf '%s\t%s\n' \
    "$CLAUDE_RULES_DEST" "claude/rules" \
    "$CLAUDE_SKILLS_DEST" "claude/skills" \
    "$COPILOT_SKILLS_DEST" "copilot/skills" \
    "$COPILOT_INSTRUCTIONS_DEST" "copilot/instructions" \
    "$PI_SKILLS_DEST" "pi/skills" \
    "$PI_EXTENSIONS_DEST" "pi/extensions" \
    "$PI_THEMES_DEST" "pi/themes" \
    "$PI_RULES_DEST" "pi/rules" \
    "$CODEX_SKILLS_DEST" "codex/skills"
}

list_clean_entries() {
  clean_targets | while IFS="$(printf '\t')" read -r dir label; do
    [ -d "$dir" ] || continue
    for entry in "$dir"/* "$dir"/.[!.]* "$dir"/..?*; do
      { [ -e "$entry" ] || [ -L "$entry" ]; } || continue
      name="$(basename "$entry")"
      if [ "$label" = "codex/skills" ] && [ "$name" = ".system" ]; then
        continue
      fi
      printf '%s/%s\t%s\n' "$label" "$name" "$entry"
    done
  done

  for entry in "$PI_LEGACY_RULES_DEST" "$CODEX_RULES_DEST"; do
    is_generated_file "$entry" || continue
    case "$entry" in
      "$PI_LEGACY_RULES_DEST") label="pi/AGENTS.md" ;;
      *) label="codex/AGENTS.md" ;;
    esac
    printf '%s\t%s\n' "$label" "$entry"
  done

  if is_owned_link "$PI_KEYBINDINGS_DEST"; then
    printf 'pi/keybindings.json\t%s\n' "$PI_KEYBINDINGS_DEST"
  fi
}

run_clean() {
  entries="$(list_clean_entries)"

  if [ -z "$entries" ]; then
    echo "clean: nothing to remove"
    return 0
  fi

  count="$(printf '%s\n' "$entries" | wc -l | tr -d ' ')"
  echo "clean: permanently removing $count item(s):"
  printf '%s\n' "$entries" | cut -f1 | sed 's/^/  /'

  if [ "$ASSUME_YES" -ne 1 ]; then
    if [ ! -t 0 ]; then
      echo "clean: refusing to run without a terminal; pass --yes to confirm" >&2
      exit 1
    fi
    printf 'Continue? [y/N] '
    read -r reply
    case "$reply" in
      y | Y | yes | YES) ;;
      *) echo "clean: aborted"; exit 1 ;;
    esac
  fi

  printf '%s\n' "$entries" | while IFS="$(printf '\t')" read -r name entry; do
    rm -rf "$entry"
    echo "removed: $name"
  done
}

remove_owned_link() {
  local target="$1" label="$2"
  if is_owned_link "$target"; then
    rm "$target"
    echo "removed: $label"
  fi
}

publish_skills() {
  dest="$1"
  label="$2"
  target_name="$3"
  mkdir -p "$dest"

  # Flatten the source hierarchy to preserve skill names and destination paths.
  for skill_dir in ${SKILL_DIRS[@]+"${SKILL_DIRS[@]}"}; do
    name="$(basename "$skill_dir")"
    target="$dest/$name"

    if ! has_target "$skill_dir/SKILL.md" "$target_name"; then
      remove_owned_link "$target" "$label/$name"
      continue
    fi

    if [ -L "$target" ]; then
      if is_owned_link "$target"; then
        ln -sfn "$skill_dir" "$target"
        echo "updated: $label/$name"
      else
        echo "skip existing: $label/$name"
      fi
    elif [ -e "$target" ]; then
      echo "skip existing: $label/$name"
    else
      ln -s "$skill_dir" "$target"
      echo "linked: $label/$name"
    fi
  done

  for target in "$dest"/*; do
    [ -L "$target" ] || continue
    is_owned_link "$target" || continue
    [ -e "$target" ] && continue
    rm "$target"
    echo "removed stale: $label/$(basename "$target")"
  done
}

package_has_prepare_script() {
  [ -f "$1/package.json" ] || return 1
  if command -v node >/dev/null 2>&1; then
    node --input-type=commonjs -e '
      const fs = require("fs");
      const pkg = JSON.parse(fs.readFileSync(process.argv[1], "utf8"));
      process.exit(pkg.scripts && pkg.scripts.prepare ? 0 : 1);
    ' "$1/package.json" || return 1
    return 0
  fi
  grep -Eq '"prepare"[[:space:]]*:' "$1/package.json"
}

install_pi_package_dependencies() {
  package="$1"
  [ -f "$package/package.json" ] || return 0

  if [ -f "$package/pnpm-lock.yaml" ]; then
    if ! command -v pnpm >/dev/null 2>&1; then
      echo "cannot install dependencies for $package: pnpm is not on PATH" >&2
      return 1
    fi

    pnpm_args=(install --dir "$package" --prod --frozen-lockfile)
    if ! package_has_prepare_script "$package"; then
      pnpm_args+=(--ignore-scripts)
    fi
    pnpm "${pnpm_args[@]}"
    return 0
  fi

  if ! command -v npm >/dev/null 2>&1; then
    echo "cannot install dependencies for $package: npm is not on PATH" >&2
    return 1
  fi

  npm_args=(install --prefix "$package" --omit=dev --no-audit --no-fund)
  if ! package_has_prepare_script "$package"; then
    npm_args+=(--ignore-scripts)
  fi
  npm "${npm_args[@]}"
}

remove_legacy_pi_cursor_sdk_package() {
  settings="$HOME/.pi/agent/settings.json"
  if [ ! -f "$settings" ] || ! grep -F "$LEGACY_PI_CURSOR_SDK_PACKAGE" "$settings" >/dev/null; then
    return 0
  fi

  if ! command -v pi >/dev/null 2>&1; then
    echo "skip removing $LEGACY_PI_CURSOR_SDK_PACKAGE: pi is not on PATH" >&2
    echo "remove that package from $settings before starting Pi so Cursor does not load twice" >&2
    return 0
  fi

  pi remove "$LEGACY_PI_CURSOR_SDK_PACKAGE"
  echo "removed package: $LEGACY_PI_CURSOR_SDK_PACKAGE"
}

publish_pi_themes() {
  mkdir -p "$PI_THEMES_DEST"

  for theme in "$PI_THEMES_SRC"/*.json; do
    [ -f "$theme" ] || continue
    name="$(basename "$theme")"
    target="$PI_THEMES_DEST/$name"

    if [ -L "$target" ]; then
      if is_owned_link "$target"; then
        ln -sfn "$theme" "$target"
        echo "updated: pi/themes/$name"
      else
        echo "skip existing: pi/themes/$name"
      fi
    elif [ -e "$target" ]; then
      echo "skip existing: pi/themes/$name"
    else
      ln -s "$theme" "$target"
      echo "linked: pi/themes/$name"
    fi
  done

  for target in "$PI_THEMES_DEST"/*; do
    [ -L "$target" ] || continue
    is_owned_link "$target" || continue
    [ -e "$target" ] && continue
    rm "$target"
    echo "removed stale: pi/themes/$(basename "$target")"
  done
}

publish_pi_keybindings() {
  mkdir -p "$(dirname "$PI_KEYBINDINGS_DEST")"
  target="$PI_KEYBINDINGS_DEST"

  if [ -L "$target" ]; then
    if is_owned_link "$target"; then
      ln -sfn "$PI_KEYBINDINGS_SRC" "$target"
      echo "updated: pi/keybindings.json"
    else
      echo "skip existing: pi/keybindings.json"
    fi
  elif [ -e "$target" ]; then
    echo "skip existing: pi/keybindings.json"
  else
    ln -s "$PI_KEYBINDINGS_SRC" "$target"
    echo "linked: pi/keybindings.json"
  fi
}

publish_claude_settings() {
  status="$(node "$MERGE_JSON" merge "$CLAUDE_SETTINGS_SRC" "$CLAUDE_SETTINGS_DEST")"
  echo "settings $status: claude/settings.json"
}

publish_pi_packages() {
  mkdir -p "$PI_EXTENSIONS_DEST"

  for package in "$PI_PACKAGES_SRC"/*; do
    [ -e "$package" ] || continue
    install_pi_package_dependencies "$package"
    name="$(basename "$package")"
    target="$PI_EXTENSIONS_DEST/$name"

    if [ -L "$target" ]; then
      if is_owned_link "$target"; then
        ln -sfn "$package" "$target"
        echo "updated: pi/extensions/$name"
      else
        echo "skip existing: pi/extensions/$name"
      fi
    elif [ -e "$target" ]; then
      echo "skip existing: pi/extensions/$name"
    else
      ln -s "$package" "$target"
      echo "linked: pi/extensions/$name"
    fi
  done

  for target in "$PI_EXTENSIONS_DEST"/*; do
    [ -L "$target" ] || continue
    is_owned_link "$target" || continue
    [ -e "$target" ] && continue
    rm "$target"
    echo "removed stale: pi/extensions/$(basename "$target")"
  done
}

prune_stale_rule_links() {
  dest="$1"
  label="$2"
  [ -d "$dest" ] || return 0
  find "$dest" -type l -print0 | while IFS= read -r -d '' target; do
    is_owned_link "$target" || continue
    [ -e "$target" ] && continue
    relative="${target#"$dest"/}"
    rm "$target"
    echo "removed stale: $label/$relative"
  done
}

publish_rules() {
  dest="$1"
  label="$2"
  target_name="$3"
  mkdir -p "$dest"
  prune_stale_rule_links "$dest" "$label"

  find "$RULES_SRC" -type f -name '*.md' -print0 | while IFS= read -r -d '' rule; do
    relative="${rule#"$RULES_SRC"/}"
    target="$dest/$relative"

    if ! has_target "$rule" "$target_name"; then
      remove_owned_link "$target" "$label/$relative"
      continue
    fi

    mkdir -p "$(dirname "$target")"
    if [ -L "$target" ]; then
      if is_owned_link "$target"; then
        ln -sfn "$rule" "$target"
        echo "updated: $label/$relative"
      else
        echo "skip existing: $label/$relative"
      fi
    elif [ -e "$target" ]; then
      echo "skip existing: $label/$relative"
    else
      ln -s "$rule" "$target"
      echo "linked: $label/$relative"
    fi
  done

  prune_stale_rule_links "$dest" "$label"
}

can_write_generated_file() {
  target="$1"
  [ ! -e "$target" ] || is_generated_file "$target"
}

install_generated_file() {
  content="$1"
  target="$2"
  label="$3"

  if ! can_write_generated_file "$target"; then
    echo "skip existing: $label"
    return 0
  fi

  mkdir -p "$(dirname "$target")"
  cp "$content" "$target"
  echo "generated: $label"
}

generated_instruction_path() {
  source="$1"
  relative="${source#"$RULES_SRC"/}"
  name="${relative%.md}"
  name="${name//\//-}"
  printf '%s/%s.instructions.md\n' "$COPILOT_INSTRUCTIONS_DEST" "$name"
}

generate_copilot_instruction() {
  source="$1"
  relative="${source#"$RULES_SRC"/}"
  target="$(generated_instruction_path "$source")"

  if ! has_target "$source" copilot; then
    if is_generated_file "$target"; then
      rm "$target"
      echo "removed: copilot/instructions/$(basename "$target")"
    fi
    return 0
  fi

  name="${relative%.md}"
  name="${name//\//-}"
  tmp="$(mktemp)"
  awk -v name="$name" -v marker="$GENERATED_MARKER from rules/$relative" '
    NR == 1 && $0 == "---" { in_frontmatter = 1; next }
    in_frontmatter && $0 == "---" {
      print "---"
      for (i = 1; i <= description_count; i++) print descriptions[i]
      printf "name: \"%s\"\n", name
      if (path_count == 1) {
        print "applyTo: " paths[1]
      } else if (path_count > 1) {
        print "applyTo:"
        for (i = 1; i <= path_count; i++) print "    - " paths[i]
      }
      print "---"
      print "<!-- " marker " -->"
      print ""
      in_frontmatter = 0
      next
    }
    in_frontmatter {
      if ($0 ~ /^description:/) {
        descriptions[++description_count] = $0
        in_paths = 0
        next
      }
      if ($0 ~ /^paths:[[:space:]]*$/) {
        in_paths = 1
        next
      }
      if (in_paths && $0 ~ /^[[:space:]]*-[[:space:]]*/) {
        line = $0
        sub(/^[[:space:]]*-[[:space:]]*/, "", line)
        paths[++path_count] = line
        next
      }
      in_paths = 0
      next
    }
    { print }
  ' "$source" > "$tmp"

  install_generated_file "$tmp" "$target" "copilot/instructions/$(basename "$target")"
  rm -f "$tmp"
}

prune_stale_generated_instructions() {
  [ -d "$COPILOT_INSTRUCTIONS_DEST" ] || return 0
  for target in "$COPILOT_INSTRUCTIONS_DEST"/*.md; do
    [ -f "$target" ] || continue
    is_generated_file "$target" || continue
    source_rel="$(sed -n "s|.*$GENERATED_MARKER from \(.*\) -->.*|\1|p" "$target" | head -1)"
    [ -n "$source_rel" ] || continue
    [ -e "$REPO_ROOT/$source_rel" ] && continue
    rm "$target"
    echo "removed stale: copilot/instructions/$(basename "$target")"
  done
}

generate_copilot_instructions() {
  find "$RULES_SRC" -type f -name '*.md' -print0 | while IFS= read -r -d '' rule; do
    generate_copilot_instruction "$rule"
  done
  prune_stale_generated_instructions
}

append_global_rule() {
  source="$1"
  relative="${source#"$RULES_SRC"/}"
  output="$2"

  printf '\n<!-- Source: rules/%s -->\n' "$relative" >> "$output"
  awk '
    NR == 1 && $0 == "---" { in_frontmatter = 1; next }
    in_frontmatter && $0 == "---" {
      if (path_count == 0) {
        print "**Applies to:** All files and tasks."
      } else {
        printf "**Applies to paths:** "
        for (i = 1; i <= path_count; i++) {
          if (i > 1) printf ", "
          printf "`%s`", paths[i]
        }
        print ""
      }
      print ""
      in_frontmatter = 0
      next
    }
    in_frontmatter {
      if ($0 ~ /^description:/) {
        in_paths = 0
        next
      }
      if ($0 ~ /^paths:[[:space:]]*$/) {
        in_paths = 1
        next
      }
      if (in_paths && $0 ~ /^[[:space:]]*-[[:space:]]*/) {
        line = $0
        sub(/^[[:space:]]*-[[:space:]]*/, "", line)
        first = substr(line, 1, 1)
        last = substr(line, length(line), 1)
        if ((first == "\"" && last == "\"") || (first == "\047" && last == "\047")) {
          line = substr(line, 2, length(line) - 2)
        }
        paths[++path_count] = line
        next
      }
      in_paths = 0
      next
    }
    { print }
  ' "$source" >> "$output"
}

install_global_rules_file() {
  content="$1"
  target="$2"
  label="$3"

  if [ -e "$target" ] && ! is_generated_file "$target"; then
    echo "cannot generate $label: $target already exists and is not managed by this repo" >&2
    echo "move its contents into rules/ or remove it, then run this script again" >&2
    return 1
  fi

  mkdir -p "$(dirname "$target")"
  cp "$content" "$target"
  echo "generated: $label"
}

generate_global_rules() {
  target_name="$1"
  destination="$2"
  label="$3"
  selected="$(mktemp)"
  output="$(mktemp)"

  find "$RULES_SRC" -type f -name '*.md' -print | sort | while IFS= read -r rule; do
    if has_target "$rule" "$target_name"; then
      printf '%s\n' "$rule"
    fi
  done > "$selected"

  if [ ! -s "$selected" ]; then
    if is_generated_file "$destination"; then
      rm "$destination"
      echo "removed: $label"
    fi
    rm -f "$selected" "$output"
    return 0
  fi

  cat > "$output" <<EOF
<!-- $GENERATED_MARKER from rules/ -->
# User Rules

These are global user instructions. Rules without path patterns always apply.
Rules with path patterns apply only when work affects matching files. Follow all
applicable rules, with more specific rules taking precedence.
EOF

  while IFS= read -r rule; do
    append_global_rule "$rule" "$output"
  done < "$selected"

  install_global_rules_file "$output" "$destination" "$label"
  rm -f "$selected" "$output"
}

validate_sources
validate_global_rules_destination codex "$CODEX_RULES_DEST" "codex/AGENTS.md"

if [ "$CLEAN" -eq 1 ]; then
  run_clean
fi

publish_skills "$CLAUDE_SKILLS_DEST" "claude/skills" claude
publish_skills "$COPILOT_SKILLS_DEST" "copilot/skills" copilot
publish_skills "$PI_SKILLS_DEST" "pi/skills" pi
publish_skills "$CODEX_SKILLS_DEST" "codex/skills" codex
publish_pi_packages
remove_legacy_pi_cursor_sdk_package
publish_pi_themes
publish_pi_keybindings
publish_rules "$CLAUDE_RULES_DEST" "claude/rules" claude
publish_claude_settings
publish_rules "$PI_RULES_DEST" "pi/rules" pi
if is_generated_file "$PI_LEGACY_RULES_DEST"; then
  rm "$PI_LEGACY_RULES_DEST"
  echo "removed: pi/AGENTS.md"
fi
generate_copilot_instructions
generate_global_rules codex "$CODEX_RULES_DEST" "codex/AGENTS.md"
